1	/**
2	 * Working out where every tile goes, on a thread that is not the one drawing
3	 * the page.
4	 *
5	 * Laying out a map of sixty tiles takes the layout engine somewhere between
6	 * fifty and a hundred and fifty milliseconds. On the thread that draws the page
7	 * that is three to nine dropped frames: the page freezes, the map stutters as it
8	 * grows, and a tool that stutters reads as a tool that is struggling. So the
9	 * work happens on a background thread, and the page carries on drawing while it
10	 * waits.
11	 *
12	 * The background thread is the layout engine's own. Its package ships the
13	 * algorithm as a script written to be run that way — ask it for a copy of that
14	 * script's address and hand the address over, and it starts the thread itself.
15	 * Writing our own wrapper thread around it, which was the first attempt, does
16	 * not work: the script checks whether it is already inside a background thread
17	 * and, finding that it is, wires itself up as that thread rather than handing
18	 * back something to call.
19	 *
20	 * Nothing on this thread ever sees a likelihood. A tile, to the layout engine,
21	 * is an identifier and a box.
22	 */
23	
24	import ELK, { type ELK as LayoutEngine } from "elkjs/lib/elk-api.js";
25	import elkWorkerAddress from "elkjs/lib/elk-worker.min.js?url";
26	import { useEffect, useMemo, useRef, useState } from "react";
27	import {
28	  type LayoutEdge,
29	  type LayoutTile,
30	  type Position,
31	  readPositions,
32	  toElkGraph,
33	} from "./elkGraph";
34	
35	/** Where every tile sits, and which run of the layout put it there. */
36	export interface Layout {
37	  /** Where each tile sits, by identifier. Empty until the first answer arrives. */
38	  readonly positions: ReadonlyMap<string, Position>;
39	  /**
40	   * How many layouts have finished.
41	   *
42	   * Zero means none has, and so nothing should be drawn yet. It goes up by one
43	   * each time, which is what lets the canvas tell "the map has just been laid
44	   * out for the first time" — frame the whole map — from "it has been laid out
45	   * again" — stay where the reader was.
46	   */
47	  readonly runs: number;
48	  /** What went wrong, in a sentence, if anything did. */
49	  readonly failure: string | null;
50	}
51	
52	/**
53	 * One background thread, shared by everything on the page that needs a layout.
54	 *
55	 * Started the first time it is asked for rather than when this file loads,
56	 * because a test running in a simulated page has no threads to start and should
57	 * not have one started for it.
58	 */
59	let engine: LayoutEngine | null = null;
60	
61	function layoutEngine(): LayoutEngine {
62	  engine ??= new ELK({ workerUrl: elkWorkerAddress });
63	  return engine;
64	}
65	
66	/** Say what went wrong in a sentence, whatever was thrown. */
67	function inWords(reason: unknown): string {
68	  return reason instanceof Error ? reason.message : "The layout engine stopped without saying why.";
69	}
70	
71	/**
72	 * Work out where every tile goes, on a background thread, and keep tiles that
73	 * have already been placed exactly where they are.
74	 *
75	 * @param tiles Every tile to place, with its height, in reading order.
76	 * @param edges Every arrow that gets a say in the left-to-right order. Feedback
77	 *   arrows are left out by the caller.
78	 */
79	export function useLayout(tiles: readonly LayoutTile[], edges: readonly LayoutEdge[]): Layout {
80	  // The map only changes when the claims or the arrows do, and comparing two
81	  // lists of strings is cheaper and steadier than comparing two arrays by
82	  // identity — a fresh array with the same contents must not start a re-layout.
83	  const shape = useMemo(
84	    () =>
85	      JSON.stringify([
86	        tiles.map((tile) => [tile.id, tile.height]),
87	        edges.map((edge) => [edge.id, edge.source, edge.target]),
88	      ]),
89	    [tiles, edges],
90	  );
91	
92	  // Where tiles already sit. Held across runs, because that is what pinning
93	  // means: this is the memory that stops a late arrival moving an early one.
94	  const placed = useRef(new Map<string, Position>());
95	  const [layout, setLayout] = useState<Layout>({
96	    positions: new Map(),
97	    runs: 0,
98	    failure: null,
99	  });
100	
101	  useEffect(() => {
102	    let stillWanted = true;
103	    const [boxes, wires] = JSON.parse(shape) as [[string, number][], [string, string, string][]];
104	    const graph = toElkGraph(
105	      boxes.map(([id, height]) => ({ id, height })),
106	      wires.map(([id, source, target]) => ({ id, source, target })),
107	      placed.current,
108	    );
109	    layoutEngine()
110	      .layout(graph)
111	      .then(
112	        (laidOut) => {
113	          if (!stillWanted) {
114	            return;
115	          }
116	          const positions = readPositions(laidOut, placed.current);
117	          placed.current = positions;
118	          setLayout((was) => ({ positions, runs: was.runs + 1, failure: null }));
119	        },
